// generated by tools/gen-how.mjs: every packages/<name>/how.ts against the fold shape.
// The shape is the HbHow props of hackbuild-ui plus name, what and how.
export interface HowSource {
  name: string;
  /** one line: what the package is */
  what: string;
  /** a few short paragraphs: how it works */
  how: string[];
  packages: string[];
  install: string;
  today?: string;
  published?: boolean;
  lang?: string;
  code: string;
  links: { page?: string; source?: string };
}
import cameras from "../packages/cameras/how.js";
import drives from "../packages/drives/how.js";
import mover from "../packages/mover/how.js";
import scenario from "../packages/scenario/how.js";
import senses from "../packages/senses/how.js";
import tunables from "../packages/tunables/how.js";

export const all: Record<string, HowSource> = { "cameras": cameras, "drives": drives, "mover": mover, "scenario": scenario, "senses": senses, "tunables": tunables };
